\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── IMF Theme Colors ──
\definecolor{primary}{HTML}{002244}     % Deep IMF Blue
\definecolor{secondary}{HTML}{334155}   % Slate Gray
\definecolor{accent}{HTML}{D97706}      % Amber / Burnt Orange
\definecolor{bgposter}{HTML}{F4F6F9}    % Light tinted background
\definecolor{redbg}{HTML}{FFFBEB}       % Amber tint card bg
\definecolor{bluebg}{HTML}{F0F4FF}      % Blue tint card bg
\definecolor{darkbg}{HTML}{F8FAFC}      % Slate tint card bg
\definecolor{redtitlebg}{HTML}{FDE6CD}  % Amber title bg
\definecolor{bluetitlebg}{HTML}{E4ECFF} % Blue title bg
\definecolor{darktitlebg}{HTML}{E2E8F0} % Slate title bg
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E5EDF5}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=12pt, parsep=4pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=12pt, parsep=4pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[6mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{4mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{accent},
    left=24pt, right=20pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=3pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{primary},
    left=24pt, right=20pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=3pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={6pt}{0pt}{secondary},
    left=24pt, right=20pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=darktitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=3pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={8pt}{0pt}{primary},
    left=24pt, right=20pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=12pt, bottomtitle=12pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{86}{100}\selectfont\bfseries Global Economy in the Shadow of War}\\[16pt]
  {\fontsize{48}{58}\selectfont IMF World Economic Outlook Trends 2024\textendash 2026}\\[12pt]
  {\fontsize{34}{44}\selectfont\color{white!80} IMF-World Bank Annual Meetings Research Symposium}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=12pt, bottom=12pt,
  valign=center, borderline south={4pt}{0pt}{primary!35},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{primary} 3.0\%\textendash 3.3\%}\\[8pt]
      {\fontsize{30}{38}\selectfont\color{textdark} Global Growth Band}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{redbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} Downside}\\[8pt]
      {\fontsize{30}{38}\selectfont\color{textdark} Balance of Risks}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{primary} 8 Editions}\\[8pt]
      {\fontsize{30}{38}\selectfont\color{textdark} WEO Reports Analyzed}\vspace{12pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══

\posterbox[redcard, title={The Big Picture}
]{name=background, column=1, between=row6 and row10}{
  \fontsize{34}{44}\selectfont
  The IMF World Economic Outlook (2024\textendash 2026) paints a picture of an increasingly fragile global economy:
  \vspace{12pt}
  \begin{itemize}
    \item Navigating geopolitical conflict, trade policy upheaval, and stubborn inflation.
    \item Growth projections remain trapped in a narrow, underwhelming band.
    \item \textbf{Central Takeaway:} Persistent mediocrity combined with growing systemic fragility.
  \end{itemize}
}

\posterbox[darkcard, title={Dominant Downside Risks}
]{name=risks, column=1, between=row10 and bottom}{
  \fontsize{34}{44}\selectfont
  Across all eight editions, the balance of risks has been consistently tilted to the downside:
  \vspace{12pt}
  \begin{itemize}
    \item \textbf{Trade Policy Escalation:} Tariff increases and retaliatory measures, front-loading activity before 2025 tariffs mask long-term damage.
    \item \textbf{Geopolitical Tensions:} Conflicts in the Middle East, the shadow of war, and broader security fragmentation.
    \item \textbf{Technology Correction:} Risk that elevated expectations for AI and tech investments face a sharp market correction.
    \item \textbf{Services Inflation:} Stubbornly persistent price pressures, especially in advanced economies, slowing the disinflation process.
  \end{itemize}
  \vspace{24pt}
  \centering
  \colorbox{accent!20}{\parbox{0.92\linewidth}{
    \centering
    \vspace{8pt}
    \textbf{Risk Outlook:} Fragility outweighs potential upside surprises.
    \vspace{8pt}
  }}
}

% ══ COLUMN 2 ══

\posterbox[bluecard, title={A Narrow Band of Mediocrity}
]{name=growth, column=2, between=row6 and row13}{
  \posterfig{0.96}{figures/growth.png}{Growth trajectory hovers around 3.2\%, well below the 3.8\% pre-pandemic average.}
  \fontsize{34}{44}\selectfont
  \begin{itemize}
    \item Global growth hasn't collapsed, but recovery remains elusive.
    \item Growth structurally slower than 2015-2019 averages.
  \end{itemize}
}

\posterbox[bluecard, title={Inflation \& Monetary Policy}
]{name=inflation, column=2, between=row13 and bottom}{
  \fontsize{34}{44}\selectfont
  Global headline inflation continues to decline, enabling central banks to ease rates, but the path is highly uneven:
  \vspace{12pt}
  \begin{itemize}
    \item \textbf{The US Exception:} Inflation projected to remain above target longer than in peer economies.
    \item \textbf{The Policy Pivot:} Late 2024 saw coordinated easing, but sticky services inflation delayed further cuts.
    \item \textbf{Renewed Pressures:} By April 2026, defense spending and supply chain disruptions reignited inflationary fears.
  \end{itemize}
}

% ══ COLUMN 3 ══

\posterbox[redcard, title={Evolving Policy Priorities}
]{name=policy, column=3, between=row6 and row14}{
  \fontsize{34}{44}\selectfont
  IMF recommendations shifted dramatically from macro stabilization to structural resilience:
  \vspace{12pt}
  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{p{0.25\linewidth} p{0.65\linewidth}}
    \rowcolor{primary!15}
    \textbf{Mid-2024} & Manage disinflation; cautious easing \\
    \textbf{Late 2024} & Policy pivot; ensure fiscal sustainability \\
    \rowcolor{primary!15}
    \textbf{Early 2025} & Rebuild fiscal buffers; address gender gaps \\
    \textbf{Mid-2025} & Restore confidence amid tariff uncertainty \\
    \rowcolor{primary!15}
    \textbf{Late 2025} & Cautious industrial policy frameworks \\
    \textbf{Early 2026} & Agile policy; manage defense trade-offs \\
  \end{tabular}
  \vspace{16pt}
  \begin{itemize}
    \item \textbf{Trend:} Moving from temporary inflation fighting to managing permanent structural and geopolitical shifts.
  \end{itemize}
}

\posterbox[highlightcard, title={Special Analytical Themes}
]{name=themes, column=3, between=row14 and bottom}{
  \fontsize{34}{44}\selectfont
  Deep-dive chapters reflect a broadening analytical lens beyond traditional macroeconomics:
  \vspace{12pt}
  \begin{enumerate}
    \item \textbf{Structural Reforms:} Building social acceptability for difficult economic transitions.
    \item \textbf{Industrial Policy:} Evaluating the real effectiveness versus the high fiscal cost of interventions.
    \item \textbf{Demographics \& Labor:} Addressing aging populations, gender disparities, and migrant skill alignment.
  \end{enumerate}
}

\end{tcbposter}
\end{document}
EOF
